std::map<int, std::string> data_cache;

data_cache[1] = "Apple";
data_cache.emplace(2, "Banana");

// Direct access (inserts default if key missing)
std::string item_1 = data_cache[1];

// Safe lookup using find (O(log N))
int key_to_find = 2;
auto lookup = data_cache.find(key_to_find);

if (lookup != data_cache.end()) {
    std::string item_2 = lookup->second;
}

// C++20 existence check
bool exists = data_cache.contains(1);

// Erasure
data_cache.erase(1);
